export default defineConfig({ test: { environment: 'node', include: ['src/lib/*.test.ts'] } });import { describe, expect, it } from 'vitest';

import { announcementSchema } from './announcement';

describe('announcementSchema', () => {
  it('parses a valid announcement', () => {
    const result = announcementSchema.safeParse({
      title: 'Road Closure Notice',
      body: 'Main street will be closed for repairs.',
      category: 'general',
    });
    expect(result.success).toBe(true);
  });

  it('rejects a missing title', () => {
    const result = announcementSchema.safeParse({
      title: '',
      body: 'Body text',
      category: 'general',
    });
    expect(result.success).toBe(false);
  });

  it('rejects a missing body', () => {
    const result = announcementSchema.safeParse({
      title: 'Title',
      body: '',
      category: 'general',
    });
    expect(result.success).toBe(false);
  });

  it('rejects an invalid category', () => {
    const result = announcementSchema.safeParse({
      title: 'Title',
      body: 'Body',
      category: 'not-a-real-category',
    });
    expect(result.success).toBe(false);
  });

  it('rejects an invalid image_url', () => {
    const result = announcementSchema.safeParse({
      title: 'Title',
      body: 'Body',
      category: 'general',
      image_url: 'not-a-url',
    });
    expect(result.success).toBe(false);
  });

  it('accepts an empty string image_url', () => {
    const result = announcementSchema.safeParse({
      title: 'Title',
      body: 'Body',
      category: 'general',
      image_url: '',
    });
    expect(result.success).toBe(true);
  });

  it('accepts a missing detailed_description', () => {
    const result = announcementSchema.safeParse({
      title: 'Title',
      body: 'Body',
      category: 'general',
    });
    expect(result.success).toBe(true);
  });

  it('accepts a valid detailed_description', () => {
    const result = announcementSchema.safeParse({
      title: 'Title',
      body: 'Body',
      category: 'general',
      detailed_description: 'A much longer write-up with the full context residents need.',
    });
    expect(result.success).toBe(true);
  });

  it('rejects a detailed_description over 5000 characters', () => {
    const result = announcementSchema.safeParse({
      title: 'Title',
      body: 'Body',
      category: 'general',
      detailed_description: 'a'.repeat(5001),
    });
    expect(result.success).toBe(false);
  });
});import { z } from 'zod';

export const announcementSchema = z.object({
  title:                z.string().min(1, 'Title is required').max(200),
  body:                 z.string().min(1, 'Body is required').max(2000),
  // Expanded write-up shown in the resident app's Announcement Modal. Optional — falls
  // back to `body` in the UI when omitted.
  detailed_description: z.string().max(5000, 'Detailed description is too long').optional().or(z.literal('')),
  category:             z.enum(['general', 'emergency', 'health', 'events']),
  image_url:            z.string().url('Must be a valid URL').optional().or(z.literal('')),
  published_at:         z.string().datetime().optional(), // ISO string; defaults to now() on insert
});

export type AnnouncementFormValues = z.infer<typeof announcementSchema>;{
